data.jsonataExpression:
symbol = "NONE-USD"
    ? $error("No cryptocurrency by that name was found.")
    : {
        "url": "https://api.exchange.coinbase.com/products/" & symbol & "/candles?granularity=86400",
        "dataType": "json"
    }

/* Coinbase lists the newest day first, as [time, low, high, open, close, volume]; today's is unfinished, so it's left out. */
(
    $coin := $[$type($) = "object"][0];
    $candles := $filter($, function($v) {$type($v) = "array"})[0];
    {
        "symbol": $coin.name & " (" & $coin.symbol & ")",
        "data": $reverse($map($filter($candles, function($c, $i) {$i > 0 and $i <= 100}), function($c) {{
            "timestamp": $fromMillis($c[0] * 1000, "[Y0001]-[M01]-[D01]"),
            "open": $c[3],
            "high": $c[2],
            "low": $c[1],
            "close": $c[4],
            "volume": $c[5]
        }}))
    }
)
